// Evaluador de juguete de políticas de control de servicios (SCP). No es código de AWS:
// aplica las reglas de la guía «SCP evaluation» leída el 16-11-2026.
const lista = (x) => (Array.isArray(x) ? x : [x]);
const coincide = (patron, valor) =>
  new RegExp('^' + patron.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + '$').test(valor);
const toca = (st, accion) => lista(st.Action).some((p) => coincide(p, accion));

const fullAccess = { Statement: [{ Effect: 'Allow', Action: '*', Resource: '*' }] };
// JSON de la guía de AWS Organizations: permite tres servicios y prohíbe salir de la organización
const permitidos = { Statement: [
  { Effect: 'Allow', Action: ['ec2:*', 'cloudwatch:*', 'organizations:*'], Resource: '*' },
  { Effect: 'Deny', Action: 'organizations:LeaveOrganization', Resource: '*' } ] };
const denegarS3 = { Statement: [{ Effect: 'Deny', Action: 's3:*', Resource: '*' }] };

// niveles: lista de listas de SCP, desde la raíz hasta la cuenta
function evaluar(niveles, accion) {
  for (const [i, nivel] of niveles.entries()) {
    const hayAllow = nivel.some((p) => p.Statement.some((s) => s.Effect === 'Allow' && toca(s, accion)));
    if (!hayAllow) return `DENEGADO: falta un Allow en el nivel ${i + 1}`;
  }
  for (const [i, nivel] of niveles.entries())
    for (const p of nivel)
      if (p.Statement.some((s) => s.Effect === 'Deny' && toca(s, accion))) return `DENEGADO: hay un Deny en el nivel ${i + 1}`;
  return 'las SCP lo dejan pasar (falta que la política de la persona lo permita)';
}

const raiz = [fullAccess], cuenta = [fullAccess];
console.log('1) todo con FullAWSAccess, s3:PutObject');
console.log('  ', evaluar([raiz, [fullAccess], cuenta], 's3:PutObject'));
console.log('2) la unidad Sandbox suma un Deny de s3:*');
console.log('  ', evaluar([raiz, [fullAccess, denegarS3], cuenta], 's3:PutObject'));
console.log('3) la unidad cambia FullAWSAccess por la lista de permitidos');
for (const a of ['ec2:RunInstances', 's3:PutObject', 'organizations:LeaveOrganization'])
  console.log('  ', a.padEnd(32), evaluar([raiz, [permitidos], cuenta], a));
console.log('4) a la cuenta se le saca FullAWSAccess y no se reemplaza');
console.log('  ', evaluar([raiz, [fullAccess], []], 'ec2:RunInstances'));

// Costos INVENTADOS (USD del mes) de una empresa ficticia. El cálculo es el de un informe por etiqueta.
const recursos = [
  { id: 'vm-01', usd: 62.4, tags: { app: 'tienda', env: 'prod', owner: 'ana' } },
  { id: 'db-01', usd: 118.0, tags: { app: 'tienda', env: 'prod', owner: 'ana' } },
  { id: 'vm-02', usd: 31.2, tags: { app: 'tienda', env: 'test', owner: 'ana' } },
  { id: 'bucket-01', usd: 9.8, tags: { app: 'fotos', env: 'prod' } },
  { id: 'vm-03', usd: 45.5, tags: { App: 'fotos', env: 'prod' } }, // «App» con mayúscula: otra clave
  { id: 'vm-04', usd: 74.1, tags: {} },
  { id: 'ip-07', usd: 3.7, tags: { app: 'tienda' } },
];
const SIN = '(sin etiqueta)';
function por(clave) {
  const g = {};
  for (const r of recursos) { const v = r.tags[clave] ?? SIN; g[v] = (g[v] ?? 0) + r.usd; }
  return g;
}
const total = recursos.reduce((a, r) => a + r.usd, 0);
console.log('Total del mes: USD', total.toFixed(2));
const g = por('app');
for (const [k, v] of Object.entries(g).sort((a, b) => b[1] - a[1]))
  console.log(`  app=${k.padEnd(15)} USD ${v.toFixed(2).padStart(7)}  ${(100 * v / total).toFixed(0)} %`);
console.log('Costo que nadie puede asignar:', (100 * g[SIN] / total).toFixed(0), '%');
